import type { UserId } from './user.js';

export interface Standing {
  readonly userId: UserId;
  readonly wins: number;
}

export class Leaderboard {
  private readonly wins: Map<UserId, number>;

  constructor(standings: readonly Standing[] = []) {
    this.wins = new Map();
    for (const standing of standings) {
      const current = this.wins.get(standing.userId) ?? 0;
      this.wins.set(standing.userId, current + standing.wins);
    }
  }

  recordWin(user: UserId): void {
    this.wins.set(user, (this.wins.get(user) ?? 0) + 1);
  }

  top(limit: number): readonly Standing[] {
    if (limit <= 0) return [];
    const standings: Standing[] = [...this.wins].map(([userId, wins]) => ({ userId, wins }));
    standings.sort((a, b) => (b.wins - a.wins) || (a.userId < b.userId ? -1 : a.userId > b.userId ? 1 : 0));
    return standings.slice(0, Math.floor(limit));
  }
}
